import{_ as a,o,c as n,a2 as r}from"./chunks/framework.Do1fvF3d.js";const m=JSON.parse('{"title":"Preguntas frecuentes","description":"","frontmatter":{},"headers":[],"relativePath":"guia/preguntas-frecuentes.md","filePath":"guia/preguntas-frecuentes.md","lastUpdated":1791064393000}'),t={name:"guia/preguntas-frecuentes.md"};function s(u,e,i,l,c,d){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h1><h2 id="¿es-gratis" tabindex="-1">¿Es gratis? <a class="header-anchor" href="#¿es-gratis" aria-label="Permalink to &quot;¿Es gratis?&quot;">​</a></h2><p>Sí. Es un proyecto de código abierto.</p><h2 id="¿tengo-que-subir-mis-contactos" tabindex="-1">¿Tengo que subir mis contactos? <a class="header-anchor" href="#¿tengo-que-subir-mis-contactos" aria-label="Permalink to &quot;¿Tengo que subir mis contactos?&quot;">​</a></h2><p>No. Aportar tu agenda es opcional y la app funciona igual sin hacerlo. Tus contactos se leen en tu teléfono para mostrar en verde a quien conoces, y eso no envía nada.</p><h2 id="¿pueden-ver-a-quien-llamo-o-quien-me-llama" tabindex="-1">¿Pueden ver a quién llamo o quién me llama? <a class="header-anchor" href="#¿pueden-ver-a-quien-llamo-o-quien-me-llama" aria-label="Permalink to &quot;¿Pueden ver a quién llamo o quién me llama?&quot;">​</a></h2><p>No guardamos quién consultó qué número. El historial de llamadas se queda en tu teléfono.</p><h2 id="¿por-que-no-aparece-el-nombre-que-yo-tengo-guardado" tabindex="-1">¿Por qué no aparece el nombre que yo tengo guardado? <a class="header-anchor" href="#¿por-que-no-aparece-el-nombre-que-yo-tengo-guardado" aria-label="Permalink to &quot;¿Por qué no aparece el nombre que yo tengo guardado?&quot;">​</a></h2><p>Un nombre solo se muestra a otros si al menos 3 personas distintas lo guardaron igual. Así, lo que escribas solo tú (por ejemplo &quot;Juan del trabajo&quot;) nunca le aparece a nadie más. En tu propio teléfono siempre ves tu nombre guardado.</p><h2 id="¿funciona-en-iphone" tabindex="-1">¿Funciona en iPhone? <a class="header-anchor" href="#¿funciona-en-iphone" aria-label="Permalink to &quot;¿Funciona en iPhone?&quot;">​</a></h2><p>Todavía no. La primera versión es para Android 10 o superior.</p><h2 id="¿que-pasa-si-no-hay-internet" tabindex="-1">¿Qué pasa si no hay internet? <a class="header-anchor" href="#¿que-pasa-si-no-hay-internet" aria-label="Permalink to &quot;¿Qué pasa si no hay internet?&quot;">​</a></h2><p>La llamada suena normalmente. Verás en verde a tus contactos y en naranja a los demás, con el aviso &quot;Sin conexión&quot;.</p><h2 id="¿como-borro-todo" tabindex="-1">¿Cómo borro todo? <a class="header-anchor" href="#¿como-borro-todo" aria-label="Permalink to &quot;¿Cómo borro todo?&quot;">​</a></h2><p>En la app: <strong>Cuenta → Borrar mi cuenta</strong>. Se borran tu cuenta, tus reportes y tus aportes.</p>',15)])])}const h=a(t,[["render",s]]);export{m as __pageData,h as default};
